css:
.fuel-order-details { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
.fuel-order-details th, .fuel-order-details td { border: 1px solid #b8b8b8; padding: 6px; text-align: left; }
.fuel-order-details th { width: 34%; }
.instruction { border: 2px solid #333; padding: 10px; }
.expiry-warning { border: 2px solid #a00; padding: 10px; font-weight: bold; }
.signature-table { width: 100%; border-collapse: separate; border-spacing: 18px 28px; margin: -18px; }
.signature-table td { width: 50%; vertical-align: top; padding: 0 18px; }
.signature-line { border-bottom: 1px solid #333; height: 34px; margin-bottom: 6px; }
